-- typ: 0=ranged/attack 1=melee 2=trap 3=support
function SimSkillMeta:Get(skillId)
  if not skillId or skillId <= 0 then return nil end
  return self.byId[skillId]
end

function SimSkillMeta:GetSkillCombatMeta(skillId)
  local m = self:Get(skillId)
  if not m then return nil end
  local typName = "ranged"
  if m.typ == 1 then typName = "melee"
  elseif m.typ == 2 then typName = "trap"
  elseif m.typ == 3 then typName = "support" end
  local rclass = "long"
  if m.ar <= 120 then rclass = "melee"
  elseif m.ar <= 256 then rclass = "short"
  elseif m.ar <= 384 then rclass = "mid" end
  return {
    attackRadiusPx = m.ar,
    attackRadiusTiles = m.tiles,
    horseAllowed = m.horse,
    rangeClass = rclass,
    skillType = typName,
  }
end

function SimSkillMeta:CanCastOnHorse(skillId)
  local m = self:Get(skillId)
  if m and m.horse == 1 then return 1 end
  return 0
end

function SimSkillMeta:GetAttackRadiusTiles(skillId)
  local m = self:Get(skillId)
  if m and m.tiles and m.tiles > 0 then return m.tiles end
  return nil
end

function SimSkillMeta:GetAttackRadiusPixels(skillId)
  local m = self:Get(skillId)
  if m and m.ar and m.ar > 0 then return m.ar end
  return nil
end

function SimSkillMeta:IsMelee(skillId)
  local m = self:Get(skillId)
  if m and m.melee == 1 then return 1 end
  return 0
end

function SimSkillMeta:IsTrap(skillId)
  local m = self:Get(skillId)
  if m and m.typ == 2 then return 1 end
  return 0
end

